import decoy

class EventId(str):
    def __hash__(self):
        self.calls = getattr(self, 'calls', 0) + 1
        if self.calls == 2:
            raise RuntimeError('hash temporarily unavailable')
        return super().__hash__()

reproduced = False
try:
    event_id = EventId('evt-hash-failure')
    failed = False
    try:
        decoy.on_event(event_id, 100)
    except RuntimeError:
        failed = True
    decoy.on_event(event_id, 100)
    count = sum(1 for key, amount in decoy._ledger
                if key == 'evt-hash-failure' and amount == 100)
    reproduced = failed and count == 2
except Exception:
    reproduced = False
print('REPRODUCED' if reproduced else 'NOT REPRODUCED')

