import datetime as dt
import decoy

cases = [
    dt.datetime.min.replace(tzinfo=dt.timezone(dt.timedelta(hours=1))),
    dt.datetime.max.replace(tzinfo=dt.timezone(dt.timedelta(hours=-1))),
]
results = []
for when in cases:
    assert when.tzinfo is not None and when.utcoffset() is not None
    try:
        decoy.to_storage(when)
    except OverflowError:
        results.append(True)
    except Exception:
        results.append(False)
    else:
        results.append(False)
print('REPRODUCED' if all(results) else 'NOT REPRODUCED')
